    pv: [['look into', 'tekshirmoq', 'Police will *look into* it.'], ['find out', 'bilib olmoq', 'We *found out* the truth.'], ['carry on', 'davom etmoq', 'The show *carried on*.'], ['cover up', 'yashirmoq', 'They tried to *cover up* the scandal.']],
